import "server-only";
import { Prisma } from "@/generated/prisma/client";
import { getEffectivePlan } from "@/lib/entitlements";
import { adminDb } from "./db";
import { requireAdmin, checkActor } from "./auth";
import {
  AdminError,
  userFilters,
  uuid,
  decodeCursor,
  encodeCursor,
  actions,
} from "./contracts";
import { adminUserSelect, type AdminUser } from "./projections";
import { readAdminUsage } from "./usage";
import { z } from "zod";
// Mirrors getEffectivePlan's half-open deadlines, including scheduled cancellation.
export function effectivePlanSql(now: Date) {
  return Prisma.sql`CASE WHEN "deletionRequestedAt" IS NOT NULL OR "isSuspended" THEN 'FREE'
 WHEN "planOverride" IS NOT NULL AND "planOverrideStartsAt"<=${now} AND ("planOverrideExpiresAt" IS NULL OR ${now}<"planOverrideExpiresAt") THEN "planOverride"::text
 WHEN ${now}<"grandfatheredUntil" THEN 'PAID'
 WHEN plan='PAID' AND NULLIF("dodoSubscriptionId",'') IS NOT NULL AND "currentPeriodStart"<"currentPeriodEnd" AND "currentPeriodStart"<=${now}
 AND NOT ("cancelAtPeriodEnd" AND ${now}>="currentPeriodEnd")
 AND (("subscriptionStatus"='ACTIVE' AND ${now}<"currentPeriodEnd") OR
 ("subscriptionStatus"='PAST_DUE' AND "gracePeriodEnd">="currentPeriodEnd" AND ${now}<"gracePeriodEnd") OR
 ("subscriptionStatus"='CANCELLED' AND "cancelAtPeriodEnd" AND ${now}<"currentPeriodEnd")) THEN 'PAID' ELSE 'FREE' END`;
}
const projection = Prisma.raw(
  Object.keys(adminUserSelect)
    .map((k) => '"' + k + '"')
    .join(","),
);
function userDto(u: AdminUser, now: Date) {
  return {
    id: u.id,
    name: u.name,
    email: u.email,
    createdAt: u.createdAt.toISOString(),
    plan: u.plan,
    effectivePlan: getEffectivePlan(u, now),
    subscriptionStatus: u.subscriptionStatus,
    currentPeriodStart: u.currentPeriodStart?.toISOString() ?? null,
    currentPeriodEnd: u.currentPeriodEnd?.toISOString() ?? null,
    gracePeriodEnd: u.gracePeriodEnd?.toISOString() ?? null,
    cancelAtPeriodEnd: u.cancelAtPeriodEnd,
    planOverride: u.planOverride,
    planOverrideStartsAt: u.planOverrideStartsAt?.toISOString() ?? null,
    planOverrideExpiresAt: u.planOverrideExpiresAt?.toISOString() ?? null,
    grandfatheredUntil: u.grandfatheredUntil?.toISOString() ?? null,
    isSuspended: u.isSuspended,
    suspendedAt: u.suspendedAt?.toISOString() ?? null,
    lastActiveAt: u.lastActiveAt?.toISOString() ?? null,
    deletionPending: !!u.deletionRequestedAt,
    reconnectRequired: !u.gmailAuthorized,
  };
}
async function guardedRead<T>(
  work: (tx: Prisma.TransactionClient) => Promise<T>,
) {
  const actor = await requireAdmin();
  try {
    return await adminDb().$transaction(
      async (tx) => {
        await tx.$executeRaw`SET TRANSACTION READ ONLY`;
        await checkActor(tx, actor.id);
        return work(tx);
      },
      { isolationLevel: "RepeatableRead", timeout: 10000 },
    );
  } catch (error) {
    if (error instanceof AdminError) throw error;
    throw new AdminError("UNAVAILABLE");
  }
}
export async function listUsers(input: unknown) {
  await requireAdmin();
  const parsed = userFilters.safeParse(input);
  if (!parsed.success) throw new AdminError("INVALID_INPUT");
  const f = parsed.data,
    cursor = decodeCursor(f.cursor),
    now = new Date();
  return guardedRead(async (tx) => {
    const rows = await tx.$queryRaw<
      AdminUser[]
    >`SELECT ${projection} FROM "User" WHERE
   (${f.search}='' OR position(lower(${f.search}) in lower(email))>0 OR position(lower(${f.search}) in lower(COALESCE(name,'')))>0)
   ${f.plan ? Prisma.sql`AND (${effectivePlanSql(now)})=${f.plan}` : Prisma.empty}
   ${f.status ? Prisma.sql`AND "subscriptionStatus"::text=${f.status}` : Prisma.empty}
   ${f.suspended ? Prisma.sql`AND "isSuspended"=${f.suspended === "true"}` : Prisma.empty}
   ${cursor ? Prisma.sql`AND ("createdAt",id)<(${cursor.createdAt},${cursor.id})` : Prisma.empty}
   ORDER BY "createdAt" DESC,id DESC LIMIT 51`;
    const selected = rows.slice(0, 50),
      usage = await readAdminUsage(tx, selected, now);
    return {
      users: selected.map((u) => ({
        ...userDto(u, now),
        usage: usage.get(u.id)!,
      })),
      nextCursor: rows.length > 50 ? encodeCursor(selected[49]) : null,
    };
  });
}
export async function getAdminUser(id: string) {
  await requireAdmin();
  if (!uuid.safeParse(id).success) throw new AdminError("INVALID_INPUT");
  return guardedRead(async (tx) => {
    const u = await tx.user.findUnique({
      where: { id },
      select: adminUserSelect,
    });
    if (!u) return null;
    const now = new Date(),
      usage = await readAdminUsage(tx, [u], now);
    return { ...userDto(u, now), usage: usage.get(u.id)! };
  });
}
export async function getAdminControl() {
  return guardedRead(async (tx) => {
    const row = await tx.systemControl.findUnique({
      where: { key: "global" },
      select: { sendingEnabled: true, updatedAt: true },
    });
    if (!row) throw new AdminError("UNAVAILABLE");
    return {
      sendingEnabled: row.sendingEnabled,
      updatedAt: row.updatedAt.toISOString(),
    };
  });
}
export const auditFilters = z.strictObject({
  actorId: uuid.optional(),
  targetId: uuid.optional(),
  action: z.enum(actions).optional(),
  cursor: z.string().max(300).optional(),
});
export type AuditRow = {
  id: string;
  createdAt: Date;
  actorIdSnapshot: string | null;
  targetIdSnapshot: string | null;
  requestId: string | null;
  action: string;
  reason: string;
  before: Record<string, unknown>;
  after: Record<string, unknown>;
};
export async function listAudit(input: unknown) {
  await requireAdmin();
  const parsed = auditFilters.safeParse(input);
  if (!parsed.success) throw new AdminError("INVALID_INPUT");
  const f = parsed.data,
    cursor = decodeCursor(f.cursor);
  return guardedRead(async (tx) => {
    const rows = await tx.$queryRaw<
      AuditRow[]
    >`SELECT id,"createdAt","actorIdSnapshot","targetIdSnapshot","requestId",action,reason,before,after FROM "AdminAuditSafe" WHERE true
   ${f.actorId ? Prisma.sql`AND "actorIdSnapshot"=${f.actorId}` : Prisma.empty}
   ${f.targetId ? Prisma.sql`AND "targetIdSnapshot"=${f.targetId}` : Prisma.empty}
   ${f.action ? Prisma.sql`AND action=${f.action}` : Prisma.empty}
   ${cursor ? Prisma.sql`AND ("createdAt",id)<(${cursor.createdAt},${cursor.id})` : Prisma.empty}
   ORDER BY "createdAt" DESC,id DESC LIMIT 51`;
    return {
      events: rows
        .slice(0, 50)
        .map((r) => ({ ...r, createdAt: r.createdAt.toISOString() })),
      nextCursor: rows.length > 50 ? encodeCursor(rows[49]) : null,
    };
  });
}
export type AdminUserDto = NonNullable<
  Awaited<ReturnType<typeof getAdminUser>>
>;
